-- 退款冲正落账：记录卖家实际扣回金额与对应佣金流水，供结算汇总复核平台承担。
-- seller_clawback_cents 允许 NULL：字段落地前的历史退款没有记录，不能把“未知”当成“扣回 0”。
ALTER TABLE "skill_market_purchases"
  ADD COLUMN IF NOT EXISTS "seller_clawback_cents" integer,
  ADD COLUMN IF NOT EXISTS "commission_flow_id" uuid;

-- 管理员结算汇总按状态 + 时间筛聚合，补组合索引。
CREATE INDEX IF NOT EXISTS "skill_market_purchases_status_time_idx"
  ON "skill_market_purchases" ("status", "created_at");
